// Some portions generated by Codex
package org.eclipse.rdf4j.sail.lmdb.frontier;

import java.io.IOException;
import java.io.OutputStream;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.Comparator;

import it.unimi.dsi.fastutil.longs.Long2IntOpenHashMap;
import it.unimi.dsi.fastutil.longs.LongOpenHashSet;

/**
 * Bounded multipass builder for the immutable base Frontier generation.
 *
 * <p>
 * A lane samples a center, never an individual edge. All adjacency rows for a selected center therefore share one
 * inclusion event and one Horvitz--Thompson adjustment. Subject and object orientations use the same design but retain
 * separate center universes. A bounded Space-Saving pass proposes heavy centers, a separate pass measures those
 * candidates exactly, and only confirmed centers whose complete adjacency fits the exact partition are removed from the
 * residual sampling universe.
 * </p>
 */
final class FrontierSynopsisBuilder {

	static final int LEGACY_RECORD_FORMAT_VERSION = 1;
	static final int RECORD_FORMAT_VERSION = 2;
	static final int RECORD_LONGS = 12;
	static final long FLAG_EXPLICIT = 1L;
	static final long FLAG_DATABASE_EXACT = 1L << 1;
	static final long FLAG_EMPTY_SNAPSHOT = 1L << 2;
	static final long FLAG_SHARED_ACROSS_LANES = 1L << 3;

	private static final int MAXIMUM_BLOCK_BYTES = 64 * 1024;
	private static final int BLOCK_OVERHEAD_BYTES = FrontierPayloadBlockWriter.MINIMUM_BLOCK_BYTES;
	private static final long HASH_VERSION_DOMAIN = 0x66726f6e74696572L;
	private static final int MAXIMUM_PROBABILITY_ADJUSTMENTS = 64;
	private static final int MAXIMUM_HEAVY_CANDIDATES_PER_DIRECTION = 4096;

	private FrontierSynopsisBuilder() {
	}

	static FrontierPayloadDescriptor build(Path directory, long generation, long budgetBytes, int designLaneCount,
			int auditLaneCount, FrontierSnapshotSource snapshot, FrontierFileOps fileOps) throws IOException {
		if (budgetBytes < BLOCK_OVERHEAD_BYTES + RECORD_LONGS * Long.BYTES) {
			throw budgetExceeded("Frontier synopsis budget cannot hold one payload record");
		}
		long rows = countRows(snapshot);
		int laneCount = Math.addExact(designLaneCount, auditLaneCount);
		long maximumRecords = maximumRecords(budgetBytes);
		HeavyPartition heavyPartition = HeavyPartition.empty();
		double inclusionProbability;
		long selectedRecords;
		if (rows == 0L) {
			selectedRecords = 1L;
			inclusionProbability = 1.0d;
		} else {
			long directionalRows = Math.multiplyExact(2L, rows);
			double completeRecords = directionalRows;
			if (completeRecords > maximumRecords) {
				heavyPartition = discoverHeavyPartition(snapshot, maximumRecords);
			}
			long residualDirectionalRows = Math.subtractExact(directionalRows,
					heavyPartition.directionalRows());
			long residualRecordBudget = Math.subtractExact(maximumRecords, heavyPartition.recordCount());
			inclusionProbability = residualDirectionalRows <= residualRecordBudget
					? 1.0d
					: chooseProbability(residualDirectionalRows, laneCount, residualRecordBudget);
			ProbabilitySelection selection = fitSelection(snapshot, designLaneCount, auditLaneCount,
					heavyPartition, maximumRecords, inclusionProbability);
			inclusionProbability = selection.probability();
			selectedRecords = selection.recordCount();
		}

		int maximumBlockBytes = (int) Math.min(MAXIMUM_BLOCK_BYTES, budgetBytes);
		int maximumBlockRecords = (int) Math.min(maximumRecords, Math.max(1,
				(maximumBlockBytes - BLOCK_OVERHEAD_BYTES) / (RECORD_LONGS * Long.BYTES)));
		FrontierPayloadBlockLimits limits = new FrontierPayloadBlockLimits(
				budgetBytes,
				maximumBlockBytes,
				maximumRecords,
				maximumBlockRecords,
				RECORD_LONGS);
		Path target = directory.resolve(payloadFileName(generation));
		Path temporary = target.resolveSibling(target.getFileName() + ".tmp");
		fileOps.createDirectories(directory);
		boolean replaced = false;
		try {
			FrontierPayloadDescriptor descriptor;
			try (OutputStream output = fileOps.openOutput(temporary)) {
				FrontierPayloadBlockWriter writer = new FrontierPayloadBlockWriter(
						output, FrontierPayloadKind.BASE, generation, limits);
				if (rows == 0L) {
					writer.writeBlock(RECORD_LONGS, emptySnapshotRecord());
				} else {
					writeSelected(snapshot, designLaneCount, auditLaneCount, heavyPartition, inclusionProbability,
							maximumBlockRecords, selectedRecords, writer);
				}
				descriptor = writer.finish();
			}
			fileOps.forceFile(temporary);
			if (descriptor.byteLength() > budgetBytes || fileOps.size(temporary) != descriptor.byteLength()) {
				throw budgetExceeded("Frontier payload exceeded its durable build envelope");
			}
			fileOps.moveAtomically(temporary, target);
			replaced = true;
			fileOps.forceDirectory(directory);
			return descriptor;
		} finally {
			if (!replaced) {
				fileOps.deleteIfExists(temporary);
			}
		}
	}

	private static long countRows(FrontierSnapshotSource snapshot) throws IOException {
		long explicit = snapshot.rowCount(true);
		long inferred = snapshot.rowCount(false);
		return Math.addExact(explicit, inferred);
	}

	private static HeavyPartition discoverHeavyPartition(FrontierSnapshotSource snapshot, long maximumRecords)
			throws IOException {
		int candidateCapacity = (int) Math.max(1L,
				Math.min(MAXIMUM_HEAVY_CANDIDATES_PER_DIRECTION, maximumRecords));
		HeavyCandidateTracker forward = new HeavyCandidateTracker(candidateCapacity);
		HeavyCandidateTracker reverse = new HeavyCandidateTracker(candidateCapacity);
		discoverHeavyCandidates(snapshot, true, forward, reverse);
		discoverHeavyCandidates(snapshot, false, forward, reverse);
		countHeavyCandidatesExactly(snapshot, true, forward, reverse);
		countHeavyCandidatesExactly(snapshot, false, forward, reverse);

		ArrayList<HeavyCandidate> candidates = new ArrayList<>(forward.size() + reverse.size());
		forward.appendExactCandidates(FrontierManifestIdentity.SUBJECT_TO_OBJECT_DIRECTION, candidates);
		reverse.appendExactCandidates(FrontierManifestIdentity.OBJECT_TO_SUBJECT_DIRECTION, candidates);
		candidates.sort(Comparator.comparingLong(HeavyCandidate::degree)
				.reversed()
				.thenComparingInt(HeavyCandidate::direction)
				.thenComparingLong(HeavyCandidate::center));

		long remainingHeavyRecords = maximumRecords / 4L;
		LongOpenHashSet forwardCenters = new LongOpenHashSet();
		LongOpenHashSet reverseCenters = new LongOpenHashSet();
		long exactDirectionalRows = 0L;
		long exactRecords = 0L;
		for (HeavyCandidate candidate : candidates) {
			if (candidate.degree() < 2L) {
				break;
			}
			long candidateRecords = candidate.degree();
			if (candidateRecords > remainingHeavyRecords) {
				continue;
			}
			LongOpenHashSet centers = candidate.direction() == FrontierManifestIdentity.SUBJECT_TO_OBJECT_DIRECTION
					? forwardCenters
					: reverseCenters;
			centers.add(candidate.center());
			exactDirectionalRows = Math.addExact(exactDirectionalRows, candidate.degree());
			exactRecords = Math.addExact(exactRecords, candidateRecords);
			remainingHeavyRecords -= candidateRecords;
		}
		return new HeavyPartition(forwardCenters, reverseCenters, exactDirectionalRows, exactRecords);
	}

	private static void discoverHeavyCandidates(FrontierSnapshotSource snapshot, boolean explicit,
			HeavyCandidateTracker forward, HeavyCandidateTracker reverse) throws IOException {
		snapshot.scan(explicit, (subject, predicate, object, context) -> {
			requireQuad(subject, predicate, object, context);
			forward.observe(subject);
			reverse.observe(object);
		});
	}

	private static void countHeavyCandidatesExactly(FrontierSnapshotSource snapshot, boolean explicit,
			HeavyCandidateTracker forward, HeavyCandidateTracker reverse) throws IOException {
		snapshot.scan(explicit, (subject, predicate, object, context) -> {
			requireQuad(subject, predicate, object, context);
			forward.observeExact(subject);
			reverse.observeExact(object);
		});
	}

	private static double chooseProbability(long population, long copiesPerMember, long maximumRecords) {
		if (population == 0L) {
			return 1.0d;
		}
		if (maximumRecords <= 0L) {
			return Math.nextUp(0.0d);
		}
		double potentialRecords = (double) population * copiesPerMember;
		if (potentialRecords <= maximumRecords) {
			return 1.0d;
		}
		double probability = maximumRecords * 0.75d / potentialRecords;
		return Math.max(Math.nextUp(0.0d), Math.min(1.0d, probability));
	}

	private static ProbabilitySelection fitSelection(FrontierSnapshotSource snapshot, int designLaneCount,
			int auditLaneCount, HeavyPartition heavyPartition, long maximumRecords, double initialProbability)
			throws IOException {
		double probability = initialProbability;
		for (int attempt = 0; attempt < MAXIMUM_PROBABILITY_ADJUSTMENTS; attempt++) {
			long selected = countSelected(snapshot, designLaneCount, auditLaneCount, heavyPartition, probability);
			if (selected > maximumRecords) {
				probability *= 0.5d;
				continue;
			}
			if (selected == 0L) {
				double increased = Math.min(1.0d, probability * 2.0d);
				if (increased == probability) {
					break;
				}
				probability = increased;
				continue;
			}
			return new ProbabilitySelection(probability, selected);
		}
		throw budgetExceeded("Frontier center sample cannot fit the configured payload budget");
	}

	private static long countSelected(FrontierSnapshotSource snapshot, int designLaneCount, int auditLaneCount,
			HeavyPartition heavyPartition, double inclusionProbability) throws IOException {
		long[] count = { 0L };
		countSelectedPlane(snapshot, true, designLaneCount, auditLaneCount, heavyPartition, inclusionProbability,
				count);
		countSelectedPlane(snapshot, false, designLaneCount, auditLaneCount, heavyPartition, inclusionProbability,
				count);
		return count[0];
	}

	private static void countSelectedPlane(FrontierSnapshotSource snapshot, boolean explicit, int designLaneCount,
			int auditLaneCount, HeavyPartition heavyPartition, double inclusionProbability, long[] count)
			throws IOException {
		snapshot.scan(explicit, (subject, predicate, object, context) -> {
			requireQuad(subject, predicate, object, context);
			count[0] = Math.addExact(count[0],
					selectedLaneCopies(subject, FrontierManifestIdentity.SUBJECT_TO_OBJECT_DIRECTION,
							designLaneCount, auditLaneCount, heavyPartition, inclusionProbability));
			count[0] = Math.addExact(count[0],
					selectedLaneCopies(object, FrontierManifestIdentity.OBJECT_TO_SUBJECT_DIRECTION,
							designLaneCount, auditLaneCount, heavyPartition, inclusionProbability));
		});
	}

	private static long selectedLaneCopies(long center, int direction, int designLaneCount, int auditLaneCount,
			HeavyPartition heavyPartition, double inclusionProbability) {
		if (heavyPartition.contains(direction, center) || inclusionProbability == 1.0d) {
			return 1L;
		}
		long count = 0L;
		for (int lane = 0; lane < designLaneCount; lane++) {
			count += selected(center, 1, lane, inclusionProbability) ? 1L : 0L;
		}
		for (int lane = 0; lane < auditLaneCount; lane++) {
			count += selected(center, 2, lane, inclusionProbability) ? 1L : 0L;
		}
		return count;
	}

	private static void writeSelected(FrontierSnapshotSource snapshot, int designLaneCount, int auditLaneCount,
			HeavyPartition heavyPartition, double inclusionProbability, int maximumBlockRecords, long expectedRecords,
			FrontierPayloadBlockWriter writer) throws IOException {
		BlockEmitter emitter = new BlockEmitter(writer, maximumBlockRecords);
		writePlane(snapshot, true, designLaneCount, auditLaneCount, heavyPartition, inclusionProbability, emitter);
		writePlane(snapshot, false, designLaneCount, auditLaneCount, heavyPartition, inclusionProbability, emitter);
		emitter.finish();
		if (emitter.recordCount != expectedRecords) {
			throw new IOException("Frontier deterministic selection changed between count and payload passes");
		}
	}

	private static void writePlane(FrontierSnapshotSource snapshot, boolean explicit, int designLaneCount,
			int auditLaneCount, HeavyPartition heavyPartition, double inclusionProbability, BlockEmitter emitter)
			throws IOException {
		snapshot.scan(explicit, (subject, predicate, object, context) -> {
			requireQuad(subject, predicate, object, context);
			emitDirection(emitter, explicit, FrontierManifestIdentity.SUBJECT_TO_OBJECT_DIRECTION,
					subject, predicate, object, context, designLaneCount, auditLaneCount,
					heavyPartition, inclusionProbability);
			emitDirection(emitter, explicit, FrontierManifestIdentity.OBJECT_TO_SUBJECT_DIRECTION,
					object, predicate, subject, context, designLaneCount, auditLaneCount,
					heavyPartition, inclusionProbability);
		});
	}

	private static void emitDirection(BlockEmitter emitter, boolean explicit, int direction,
			long center, long predicate, long neighbor, long context, int designLaneCount, int auditLaneCount,
			HeavyPartition heavyPartition, double inclusionProbability) throws IOException {
		if (heavyPartition.contains(direction, center) || inclusionProbability == 1.0d) {
			emitSharedExact(emitter, explicit, direction, center, predicate, neighbor, context);
			return;
		}
		for (int lane = 0; lane < designLaneCount; lane++) {
			emitIfSelected(emitter, explicit, direction, FrontierManifestIdentity.DESIGN_LANE_ROLE, lane,
					center, predicate, neighbor, context, inclusionProbability);
		}
		for (int lane = 0; lane < auditLaneCount; lane++) {
			emitIfSelected(emitter, explicit, direction, FrontierManifestIdentity.AUDIT_LANE_ROLE, lane,
					center, predicate, neighbor, context, inclusionProbability);
		}
	}

	private static void emitIfSelected(BlockEmitter emitter, boolean explicit, int direction, int laneRole,
			int laneIndex, long center, long predicate, long neighbor, long context, double inclusionProbability)
			throws IOException {
		long laneHash = laneHash(center, laneRole, laneIndex);
		if (!selected(laneHash, inclusionProbability)) {
			return;
		}
		long flags = explicit ? FLAG_EXPLICIT : 0L;
		emitter.append(
				RECORD_FORMAT_VERSION,
				direction,
				laneRole,
				laneIndex,
				flags,
				center,
				predicate,
				neighbor,
				context,
				Double.doubleToRawLongBits(1.0d / inclusionProbability),
				Double.doubleToRawLongBits(inclusionProbability),
				laneHash);
	}

	private static void emitSharedExact(BlockEmitter emitter, boolean explicit, int direction,
			long center, long predicate, long neighbor, long context) throws IOException {
		long flags = FLAG_DATABASE_EXACT | FLAG_SHARED_ACROSS_LANES;
		if (explicit) {
			flags |= FLAG_EXPLICIT;
		}
		emitter.append(
				RECORD_FORMAT_VERSION,
				direction,
				FrontierManifestIdentity.ALL_LANE_ROLES,
				-1L,
				flags,
				center,
				predicate,
				neighbor,
				context,
				Double.doubleToRawLongBits(1.0d),
				Double.doubleToRawLongBits(1.0d),
				0L);
	}

	private static boolean selected(long center, int laneRole, int laneIndex, double probability) {
		return selected(laneHash(center, laneRole, laneIndex), probability);
	}

	static boolean selected(long hash, double probability) {
		if (probability == 1.0d) {
			return true;
		}
		double unit = (hash >>> 11) * 0x1.0p-53;
		return unit < probability;
	}

	static long laneHash(long center, int laneRole, int laneIndex) {
		long value = center ^ HASH_VERSION_DOMAIN;
		value ^= 0x9e3779b97f4a7c15L * (laneIndex + 1L);
		value ^= laneRole == 1 ? 0x243f6a8885a308d3L : 0x13198a2e03707344L;
		value ^= value >>> 30;
		value *= 0xbf58476d1ce4e5b9L;
		value ^= value >>> 27;
		value *= 0x94d049bb133111ebL;
		return value ^ value >>> 31;
	}

	private static long maximumRecords(long budgetBytes) {
		long pessimisticRecordBytes = RECORD_LONGS * Long.BYTES + BLOCK_OVERHEAD_BYTES;
		return Math.max(1L, budgetBytes / pessimisticRecordBytes);
	}

	private static String payloadFileName(long generation) {
		return "payload-" + FrontierPayloadKind.BASE.fileToken() + "-" + generation + ".bin";
	}

	private static long[] emptySnapshotRecord() {
		return new long[] {
				RECORD_FORMAT_VERSION,
				FrontierManifestIdentity.SUBJECT_TO_OBJECT_DIRECTION,
				1L,
				0L,
				FLAG_DATABASE_EXACT | FLAG_EMPTY_SNAPSHOT,
				0L,
				0L,
				0L,
				0L,
				Double.doubleToRawLongBits(0.0d),
				Double.doubleToRawLongBits(1.0d),
				0L
		};
	}

	private static void requireQuad(long subject, long predicate, long object, long context) throws IOException {
		if (subject <= 0L || predicate <= 0L || object <= 0L || context < 0L) {
			throw new IOException("Frontier snapshot emitted an invalid primitive RDF quad");
		}
	}

	private static FrontierPayloadException budgetExceeded(String message) {
		return new FrontierPayloadException(FrontierSynopsisStatus.BUDGET_EXCEEDED, message);
	}

	private record ProbabilitySelection(double probability, long recordCount) {
	}

	private record HeavyCandidate(int direction, long center, long degree) {
	}

	private record HeavyPartition(
			LongOpenHashSet forwardCenters,
			LongOpenHashSet reverseCenters,
			long directionalRows,
			long recordCount) {

		private static HeavyPartition empty() {
			return new HeavyPartition(new LongOpenHashSet(), new LongOpenHashSet(), 0L, 0L);
		}

		private boolean contains(int direction, long center) {
			return switch (direction) {
			case FrontierManifestIdentity.SUBJECT_TO_OBJECT_DIRECTION -> forwardCenters.contains(center);
			case FrontierManifestIdentity.OBJECT_TO_SUBJECT_DIRECTION -> reverseCenters.contains(center);
			default -> false;
			};
		}
	}

	/**
	 * Primitive bounded Space-Saving table. Candidate membership is approximate, but every retained candidate is
	 * measured in a separate exact pass before it can enter the heavy partition.
	 */
	private static final class HeavyCandidateTracker {

		private final long[] centers;
		private final long[] estimatedCounts;
		private final long[] exactCounts;
		private final int[] heap;
		private final int[] heapPositions;
		private final Long2IntOpenHashMap slotsByCenter;
		private int size;

		private HeavyCandidateTracker(int capacity) {
			centers = new long[capacity];
			estimatedCounts = new long[capacity];
			exactCounts = new long[capacity];
			heap = new int[capacity];
			heapPositions = new int[capacity];
			slotsByCenter = new Long2IntOpenHashMap(capacity);
			slotsByCenter.defaultReturnValue(-1);
		}

		private int size() {
			return size;
		}

		private void observe(long center) {
			int slot = slotsByCenter.get(center);
			if (slot >= 0) {
				estimatedCounts[slot] = Math.incrementExact(estimatedCounts[slot]);
				int position = heapPositions[slot];
				if (position < size >>> 1) {
					siftDown(position);
				}
				return;
			}
			if (size < centers.length) {
				slot = size;
				centers[slot] = center;
				estimatedCounts[slot] = 1L;
				heap[size] = slot;
				heapPositions[slot] = size;
				slotsByCenter.put(center, slot);
				size++;
				siftUp(size - 1);
				return;
			}
			slot = heap[0];
			slotsByCenter.remove(centers[slot]);
			centers[slot] = center;
			estimatedCounts[slot] = Math.incrementExact(estimatedCounts[slot]);
			exactCounts[slot] = 0L;
			slotsByCenter.put(center, slot);
			siftDown(0);
		}

		private void observeExact(long center) {
			int slot = slotsByCenter.get(center);
			if (slot >= 0) {
				exactCounts[slot] = Math.incrementExact(exactCounts[slot]);
			}
		}

		private void appendExactCandidates(int direction, ArrayList<HeavyCandidate> output) {
			for (int slot = 0; slot < size; slot++) {
				if (exactCounts[slot] > 0L) {
					output.add(new HeavyCandidate(direction, centers[slot], exactCounts[slot]));
				}
			}
		}

		private void siftUp(int position) {
			int slot = heap[position];
			while (position > 0) {
				int parent = (position - 1) >>> 1;
				int parentSlot = heap[parent];
				if (!less(slot, parentSlot)) {
					break;
				}
				heap[position] = parentSlot;
				heapPositions[parentSlot] = position;
				position = parent;
			}
			heap[position] = slot;
			heapPositions[slot] = position;
		}

		private void siftDown(int position) {
			int slot = heap[position];
			int half = size >>> 1;
			while (position < half) {
				int child = (position << 1) + 1;
				int childSlot = heap[child];
				int right = child + 1;
				if (right < size && less(heap[right], childSlot)) {
					child = right;
					childSlot = heap[right];
				}
				if (!less(childSlot, slot)) {
					break;
				}
				heap[position] = childSlot;
				heapPositions[childSlot] = position;
				position = child;
			}
			heap[position] = slot;
			heapPositions[slot] = position;
		}

		private boolean less(int leftSlot, int rightSlot) {
			long leftCount = estimatedCounts[leftSlot];
			long rightCount = estimatedCounts[rightSlot];
			return leftCount < rightCount
					|| leftCount == rightCount && centers[leftSlot] < centers[rightSlot];
		}
	}

	private static final class BlockEmitter {

		private final FrontierPayloadBlockWriter writer;
		private final long[] values;
		private int valueCount;
		private long recordCount;

		private BlockEmitter(FrontierPayloadBlockWriter writer, int maximumBlockRecords) {
			this.writer = writer;
			this.values = new long[Math.multiplyExact(maximumBlockRecords, RECORD_LONGS)];
		}

		private void append(long value0, long value1, long value2, long value3, long value4, long value5,
				long value6, long value7, long value8, long value9, long value10, long value11) throws IOException {
			if (valueCount == values.length) {
				flush();
			}
			values[valueCount] = value0;
			values[valueCount + 1] = value1;
			values[valueCount + 2] = value2;
			values[valueCount + 3] = value3;
			values[valueCount + 4] = value4;
			values[valueCount + 5] = value5;
			values[valueCount + 6] = value6;
			values[valueCount + 7] = value7;
			values[valueCount + 8] = value8;
			values[valueCount + 9] = value9;
			values[valueCount + 10] = value10;
			values[valueCount + 11] = value11;
			valueCount += RECORD_LONGS;
			recordCount = Math.incrementExact(recordCount);
		}

		private void finish() throws IOException {
			flush();
		}

		private void flush() throws IOException {
			if (valueCount == 0) {
				return;
			}
			long[] block = valueCount == values.length ? values : java.util.Arrays.copyOf(values, valueCount);
			writer.writeBlock(RECORD_LONGS, block);
			valueCount = 0;
		}
	}
}
